package com.cowave.search.auth.model

import org.bson.types.ObjectId
import org.springframework.data.annotation.Id
import org.springframework.data.mongodb.core.index.Indexed
import org.springframework.data.mongodb.core.mapping.Document
import java.time.LocalDateTime

/**
 * SSO 사용자 로컬 권한 매핑 도큐먼트.
 *
 * - 비밀번호는 SSO 제공자가 관리하므로 저장하지 않음
 * - roleId: Role 컬렉션의 ID를 직접 임베딩 (UserRole 별도 컬렉션 불필요)
 */
@Document(collection = "users")
data class User(
    @Id
    val id: String = ObjectId.get().toHexString(),
    var username: String,
    @Indexed(unique = true)
    var email: String,
    var roleId: String? = null,
    val createDate: LocalDateTime = LocalDateTime.now(),
    var updateDate: LocalDateTime = LocalDateTime.now(),
)

package com.cowave.search.auth.service

import com.cowave.search.auth.dto.AuthUserResponse
import com.cowave.search.auth.infrastructure.UserRepository
import com.cowave.search.common.exception.NotFoundUserException
import org.springframework.stereotype.Service

@Service
class AuthService(
    private val userRepository: UserRepository,
) {
    /**
     * SSO 토큰의 email 클레임으로 로컬 사용자 및 권한 조회.
     * roleId는 User 도큐먼트에 직접 임베딩되어 있음.
     */
    fun getCurrentUser(email: String): AuthUserResponse {
        val user =
            userRepository
                .findByEmail(email)
                .orElseThrow { NotFoundUserException("존재하지 않는 사용자입니다: $email") }

        return AuthUserResponse(
            id = user.id,
            username = user.username,
            email = user.email,
            roleId = user.roleId,
        )
    }
}

