package com.cowave.search.auth.service

import com.cowave.search.auth.dto.AuthUserResponse
import com.cowave.search.auth.infrastructure.UserRepository
import com.cowave.search.auth.model.User
import com.cowave.search.common.security.SsoUserInfo
import org.springframework.stereotype.Service

@Service
class AuthService(
    private val userRepository: UserRepository,
) {
    /**
     * SSO 토큰에서 추출한 사용자 정보로 로컬 User 조회 또는 자동 생성.
     * 최초 접근 시 SSO 사용자를 로컬 DB에 등록.
     */
    fun getOrCreateUser(ssoUserInfo: SsoUserInfo): AuthUserResponse {
        val user =
            userRepository.findByEmail(ssoUserInfo.email).orElseGet {
                userRepository.save(
                    User(
                        username = ssoUserInfo.username,
                        email = ssoUserInfo.email,
                    ),
                )
            }

        return AuthUserResponse(
            id = user.id,
            username = user.username,
            email = user.email,
            roles = user.roles,
        )
    }

    fun getCurrentUser(email: String): AuthUserResponse {
        val user =
            userRepository
                .findByEmail(email)
                .orElseThrow { NoSuchElementException("존재하지 않는 사용자입니다: $email") }

        return AuthUserResponse(
            id = user.id,
            username = user.username,
            email = user.email,
            roles = user.roles,
        )
    }
}

package com.cowave.search.auth.controller

import com.cowave.search.auth.dto.AuthUserResponse
import com.cowave.search.auth.service.AuthService
import com.cowave.search.common.security.SsoUserInfo
import org.springframework.http.ResponseEntity
import org.springframework.security.core.context.SecurityContextHolder
import org.springframework.web.bind.annotation.GetMapping
import org.springframework.web.bind.annotation.RequestMapping
import org.springframework.web.bind.annotation.RestController

@RestController
@RequestMapping("/auth")
class AuthController(
    private val authService: AuthService,
) {
    /**
     * 현재 SSO 로그인 사용자 정보 반환.
     * SecurityContext의 SsoUserInfo로 로컬 User 조회 또는 자동 생성.
     */
    @GetMapping
    fun getCurrentUser(): ResponseEntity<AuthUserResponse> {
        val ssoUserInfo =
            SecurityContextHolder.getContext().authentication?.principal as? SsoUserInfo
                ?: return ResponseEntity.status(401).build()
        return ResponseEntity.ok(authService.getOrCreateUser(ssoUserInfo))
    }
}

package com.cowave.search.auth.service

import com.cowave.search.auth.dto.AddUserRequest
import com.cowave.search.auth.dto.EditProfileRequest
import com.cowave.search.auth.dto.UserResponse
import com.cowave.search.auth.infrastructure.UserRepository
import com.cowave.search.auth.model.User
import com.cowave.search.common.exception.DuplicatedUserException
import com.cowave.search.common.exception.NotFoundUserException
import org.springframework.stereotype.Service
import java.time.Instant

@Service
class UserService(
    private val userRepository: UserRepository,
) {
    fun findAll(): List<UserResponse> = userRepository.findAll().map { UserResponse.from(it) }

    fun findById(id: String): UserResponse {
        val user =
            userRepository
                .findById(id)
                .orElseThrow { NotFoundUserException("존재하지 않는 사용자입니다: $id") }
        return UserResponse.from(user)
    }

    fun create(request: AddUserRequest): UserResponse {
        if (userRepository.existsByEmail(request.email)) {
            throw DuplicatedUserException("이미 사용 중인 이메일입니다: ${request.email}")
        }

        val user =
            userRepository.save(
                User(
                    username = request.username,
                    email = request.email,
                    roles = request.roles,
                ),
            )

        return UserResponse.from(user)
    }

    fun delete(id: String) {
        userRepository
            .findById(id)
            .orElseThrow { NotFoundUserException("존재하지 않는 사용자입니다: $id") }
        userRepository.deleteById(id)
    }

    fun editProfile(
        id: String,
        request: EditProfileRequest,
    ): UserResponse {
        val user =
            userRepository
                .findById(id)
                .orElseThrow { NotFoundUserException("존재하지 않는 사용자입니다: $id") }

        if (user.email != request.email && userRepository.existsByEmail(request.email)) {
            throw DuplicatedUserException("이미 사용 중인 이메일입니다: ${request.email}")
        }

        val updated =
            user.copy(
                username = request.username,
                email = request.email,
                roles = request.roles,
                updatedAt = Instant.now(),
            )
        userRepository.save(updated)

        return UserResponse.from(updated)
    }
}

