            userRepository
                .findById(id)
                .orElseThrow { NotFoundUserException("존재하지 않는 사용자입니다: $id") }

        if (user.email != request.email && userRepository.existsByEmail(request.email)) {
            throw DuplicatedUserException("이미 사용 중인 이메일입니다: ${request.email}")
        }

        val updated =
            user.copy(
                username = request.username,
                email = request.email,
                roles = request.roles,
                updatedAt = Instant.now(),
            )
        userRepository.save(updated)

        return UserResponse.from(updated)
    }
}

package com.cowave.search.auth.controller

import com.cowave.search.auth.dto.AuthUserResponse
import com.cowave.search.auth.service.AuthService
import com.cowave.search.common.security.SsoUserInfo
import org.springframework.http.ResponseEntity
import org.springframework.security.core.context.SecurityContextHolder
import org.springframework.web.bind.annotation.GetMapping
import org.springframework.web.bind.annotation.RequestMapping
import org.springframework.web.bind.annotation.RestController

@RestController
@RequestMapping("/auth")
class AuthController(
    private val authService: AuthService,
) {
    /**
     * 현재 SSO 로그인 사용자 정보 반환.
     * SecurityContext의 SsoUserInfo로 로컬 User 조회 또는 자동 생성.
     */
    @GetMapping
    fun getCurrentUser(): ResponseEntity<AuthUserResponse> {
        val ssoUserInfo =
            SecurityContextHolder.getContext().authentication?.principal as? SsoUserInfo
                ?: return ResponseEntity.status(401).build()
        return ResponseEntity.ok(authService.getOrCreateUser(ssoUserInfo))
    }
}

package com.cowave.search.common.security

import com.auth0.jwt.JWT
import com.auth0.jwt.exceptions.JWTVerificationException
import org.slf4j.LoggerFactory
import org.springframework.stereotype.Component

/**
 * com.auth0:java-jwt 기반 SSO 토큰 검증 구현체.
 *
 * SSO 제공자가 미확정인 현재, 기존 JWT 라이브러리를 재활용하여 토큰을 검증.
 * SSO 제공자 확정 시 OidcSsoTokenVerifier로 교체 가능.
 */
@Component
class CustomSsoTokenVerifier(
    private val ssoProperties: SsoProperties,
) : SsoTokenVerifier {
    private val log = LoggerFactory.getLogger(javaClass)

    override fun verify(token: String): SsoUserInfo? {
        return try {
            val decoded = JWT.decode(token)

            val email = decoded.getClaim("email")?.asString()
            val username =
                decoded.getClaim("preferred_username")?.asString()
                    ?: decoded.getClaim("name")?.asString()
                    ?: email
            val roles =
                decoded.getClaim(ssoProperties.roleClaim)?.asList(String::class.java)
                    ?: emptyList()

            if (email.isNullOrBlank()) {
                log.warn("SSO 토큰에 email 클레임이 없습니다")
                return null
            }

            SsoUserInfo(
                userId = decoded.subject ?: email,
                username = username ?: email,
                email = email,
                roles = roles,
            )
        } catch (e: JWTVerificationException) {
            log.warn("SSO 토큰 검증 실패: {}", e.message)
            null
        } catch (e: Exception) {
            log.warn("SSO 토큰 파싱 실패: {}", e.message)
            null
        }
    }
}

package com.cowave.search.config

import com.cowave.search.common.security.SsoProperties
import com.cowave.search.common.security.SsoTokenAuthenticationFilter
import org.springframework.context.annotation.Bean
import org.springframework.context.annotation.Configuration
import org.springframework.http.HttpStatus
import org.springframework.security.config.annotation.web.builders.HttpSecurity
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity
import org.springframework.security.config.http.SessionCreationPolicy
import org.springframework.security.web.SecurityFilterChain
import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter

@Configuration
@EnableWebSecurity
class SecurityConfig(
    private val ssoProperties: SsoProperties,
    private val ssoTokenAuthenticationFilter: SsoTokenAuthenticationFilter,
) {
    @Bean
    fun securityFilterChain(http: HttpSecurity): SecurityFilterChain {
        val bypassUris = ssoProperties.bypassUri.toTypedArray()

        http
            .csrf { it.disable() }
            .sessionManagement { it.sessionCreationPolicy(SessionCreationPolicy.STATELESS) }
            .authorizeHttpRequests { auth ->
                auth.requestMatchers(*bypassUris).permitAll()
                auth.anyRequest().authenticated()
            }.addFilterBefore(ssoTokenAuthenticationFilter, UsernamePasswordAuthenticationFilter::class.java)
            .exceptionHandling { ex ->
                ex.authenticationEntryPoint { _, response, _ ->
                    response.status = HttpStatus.UNAUTHORIZED.value()
                    response.contentType = "application/json;charset=UTF-8"
                    response.writer.write("""{"message":"Unauthorized"}""")
                }
            }

        return http.build()
    }
}

package com.cowave.search.auth.model

import org.bson.types.ObjectId
import org.springframework.data.annotation.Id
import org.springframework.data.mongodb.core.index.CompoundIndex
import org.springframework.data.mongodb.core.mapping.Document
import java.time.Instant

@Document(collection = "users")
@CompoundIndex(def = "{'email': 1}", unique = true)
data class User(
    @Id
    val id: String = ObjectId.get().toHexString(),
    var username: String,
    var email: String,
    var roles: List<Role> = emptyList(),
    val createdAt: Instant = Instant.now(),
    var updatedAt: Instant = Instant.now(),
)

/**
 * Embedded role within User document.
 * 1차: 기존 4개 boolean 권한 유지.
 * permissions 필드는 향후 SSO 역할 매핑 세분화 시 활용.
 */
data class Role(
    val name: String,
    val analysis: Boolean = false,
    val index: Boolean = false,
    val search: Boolean = false,
    val manage: Boolean = false,
    val permissions: List<String> = emptyList(),
)

